DECLARE MenuChoice : CHAR
OUTPUT "1: Add record  2: Delete record  3: Search  Anything else: Quit"
INPUT MenuChoice

CASE OF MenuChoice
  '1' : OUTPUT "Adding a new record"
  '2' : OUTPUT "Deleting a record"
  '3' : OUTPUT "Searching for a record"
  OTHERWISE : OUTPUT "Exiting the program"
ENDCASE

// If MenuChoice = '2', only the line OUTPUT "Deleting a record" executes;
// the other three branches, including OTHERWISE, are all skipped.
// If MenuChoice = 'X' (not listed), only OTHERWISE executes, printing "Exiting the program".
